es=['Saludar','¿Qué tiempo hace?','¿Qué día es?','¿Qué hora es?','¿Cómo te sientes?','Su pasado','Hablar de la horda','Rumores sobre mí','No te haré daño','Contar un chiste','Dar objeto de la mano','Curar con venda','Invitar a mi facción','Mochila y equipo','Despedir compañero','Sígueme','Quédate aquí','Patrulla esta zona','Cosecha y replanta','Busca suministros','Limpia cadáveres','Fabrica útiles','Cocina en un horno','Entrégame lo recogido','Actúa por tu cuenta','Autorizar almacén cercano']
