pairs={
'greet':(['Tranquilo. Ese gesto de agacharme significa paz.','Otro superviviente... Mantengamos las manos a la vista.','Hola. Todavía queda gente viva, por lo que veo.','Te he visto llegar. ¿Vienes a hablar?'],['Easy. Crouching like that means peace.','Another survivor... Let us keep our hands where we can see them.','Hello. There are still people alive, then.','I saw you approaching. Are you here to talk?']),
'clear':(['El cielo está despejado. Buen momento para salir.','Ahora no llueve. Aprovecha para reunir agua y comida.','Con esta luz es más fácil ver quién se acerca.','Está despejado; no significa que el camino sea seguro.'],['Clear skies. A good time to go outside.','No rain right now. Use the time to gather supplies.','This light makes it easier to see who is approaching.','Clear weather does not mean a safe road.']),
'rain':(['Está lloviendo. Busquemos un techo.','La lluvia tapa algunos ruidos. No te confíes.','Con todo mojado prefiero quedarme bajo techo.','Llueve. No quiero pasar la noche con la ropa empapada.'],['It is raining. Let us find a roof.','The rain covers some noises. Stay alert.','Everything is wet. I would rather stay indoors.','Rain. I do not want to spend the night in soaked clothes.']),
'storm':(['Hay tormenta. No es buen momento para cruzar campo abierto.','Los truenos me ponen nervioso. Apenas oigo los pasos.','Está tronando. Necesitamos refugio.','Con esta tormenta prefiero esperar bajo techo.'],['A storm. This is no time to cross open ground.','Thunder makes me nervous. I can barely hear footsteps.','Thunder. We need shelter.','I would rather wait indoors during this storm.']),
'day':(['Según mi cuenta, es el día %s.','Llevamos aproximadamente %s días.','Mi cuenta del día marca %s.','Hoy sería el día %s de este mundo.'],['By my count, it is day %s.','It has been roughly %s days.','My day count says %s.','This would be day %s in this world.']),
'time':(['Son aproximadamente las %2$s:00.','Calculo que son las %2$s:00.','La hora del mundo marca las %2$s:00.','Ahora son cerca de las %2$s:00.'],['It is approximately %2$s:00.','I reckon it is about %2$s:00.','The world clock says %2$s:00.','It is around %2$s:00 now.']),
'calm':(['Por ahora estoy tranquilo. Eso ya es bastante.','He tenido días peores. Todavía puedo seguir.','No veo peligro inmediato. Me ayuda hablar.','Estoy bien, de momento. No bajemos la guardia.'],['I am calm for now. That is already something.','I have had worse days. I can still keep going.','No immediate danger. Talking helps.','I am fine for now. Let us stay alert.']),
'wounded':(['Estoy herido. Una venda me vendría bien.','Me duele todo. Necesito curarme antes de seguir.','No estoy para correr. ¿Tienes material médico?','Estoy bastante mal. No me dejes atrás.'],['I am hurt. A bandage would help.','Everything hurts. I need treatment before moving on.','I am in no shape to run. Do you have medical supplies?','I am in a bad way. Please do not leave me behind.']),
'horde':(['Son demasiados. Necesitamos una salida.','¡Una horda! No nos encerremos aquí.','Con tantos zombis prefiero replegarme.','No gastes todas las balas. Tenemos que sobrevivir.'],['Too many. We need a way out.','A horde! Do not let us get trapped here.','With that many zombies I would rather fall back.','Do not waste all your bullets. We need to survive.']),
'crowd':(['Hay mucha gente junta. Me pone nervioso.','Demasiadas personas haciendo ruido aquí.','Con tanta gente no sé a quién mirar primero.','Haced sitio. No me gusta quedarme rodeado.'],['Too many people together. It makes me nervous.','A lot of people making noise here.','With so many people I do not know where to look first.','Give me some space. I do not like being surrounded.']),
'night':(['Ya es de noche. Hay que tener cuidado.','De noche me cuesta ver de dónde vienen.','Preferiría encontrar refugio antes de seguir.','La oscuridad nunca trae buenas noticias.'],['Night already. We need to be careful.','At night it is harder to see where they are coming from.','I would rather find shelter before moving on.','Darkness rarely brings good news.']),
'feeling':(['Sigo vivo. Hoy me conformo con eso.','Aún me quedan fuerzas.','Un poco cansado, pero puedo seguir.','Hablemos cuando estemos a salvo.'],['Still alive. That will do for today.','I still have some strength left.','A little tired, but I can keep going.','Let us talk once we are safe.']),
'past':(['Antes pensaba que mi trabajo era duro. No sabía nada.','Solía preocuparme por llegar tarde. Ahora me preocupa llegar vivo.','Tuve una vida antes de todo esto. Todavía intento recordarla.','Prefiero no hablar de quienes dejé atrás.'],['I used to think my job was hard. I knew nothing.','I used to worry about being late. Now I worry about arriving alive.','I had a life before all this. I still try to remember it.','I would rather not talk about the people I left behind.']),
'rumor':(['La gente comparte lo que ve. Tus actos pesan más que tus palabras.','Si ayudas, se acaba sabiendo. Si haces daño, también.','Lo que haces delante de otros no se queda en secreto.','He hablado con otros supervivientes. Ten cuidado con la fama que construyes.'],['People share what they see. Your actions matter more than your words.','People hear when you help. They also hear when you hurt others.','What you do in front of others does not stay secret.','I have talked to other survivors. Be careful with the reputation you build.']),
'promise':(['Me gustaría creerte. Demuéstralo con tus actos.','Despacio. La confianza no aparece de golpe.','Gracias por decirlo. Mantén esa promesa.','No necesito discursos. Necesito saber que puedo fiarme.'],['I would like to believe you. Show me through your actions.','Slowly. Trust does not appear all at once.','Thank you for saying that. Keep your promise.','I do not need speeches. I need to know I can trust you.']),
'joke':(['No esperaba reírme hoy. Gracias.','Un chiste malo sigue siendo mejor que otro grito.','Vaya momento para bromear... Aunque me hacía falta.','Cuando todo esto pase, tendrás que buscar chistes mejores.'],['I did not expect to laugh today. Thank you.','A bad joke is still better than another scream.','What a time for a joke... Though I needed that.','When this is over, you will need better jokes.']),
'plead':(['Baja el arma, por favor. No quiero problemas.','No dispares. Podemos hablar.','¡Tranquilo! No voy a atacarte.','No me hagas daño. Solo intento sobrevivir.'],['Please lower the weapon. I do not want trouble.','Do not shoot. We can talk.','Easy! I am not going to attack you.','Do not hurt me. I am just trying to survive.']),
}
responses={
 'thanks':('Gracias. Esto me ayudará a seguir vivo.','Thank you. This will help me stay alive.'),'no_gift':('Lleva un suministro útil en la mano. Necesito espacio y un momento entre regalos.','Hold a useful supply. I need space and some time between gifts.'),'healing':('Si tienes una venda en la mano, puedes curarme estando cerca.','You can treat me at close range while holding a bandage.'),'already':('Ya pertenezco a un grupo.','I already belong to a group.'),'no_faction':('Primero necesitas pertenecer a una facción.','You need to belong to a faction first.'),'refuse':('Aún no confío lo suficiente. Habla conmigo, ayúdame o comparte suministros.','I do not trust you enough yet. Talk to me, help me or share supplies.'),'joined':('Está bien. Voy contigo. No me hagas arrepentirme.','All right. I am coming with you. Do not make me regret this.'),'not_ally':('Solo mis compañeros pueden darme órdenes o revisar mi equipo.','Only my companions can give orders or inspect my equipment.'),'dismissed':('Nuestros caminos se separan. Cuídate.','Our paths part here. Take care.'),'no_depot':('Acércate a un cofre, barril, horno o ahumador y vuelve a intentarlo.','Move near a chest, barrel, furnace or smoker and try again.'),'depot_set':('Usaré ese almacén como punto de suministros.','I will use that storage as a supply point.'),'order':('Entendido. Haré lo que pueda con el equipo y los recursos que tenga.','Understood. I will do what I can with my equipment and supplies.')}
