personas={
'kind':(['Si necesitas ayuda, dímelo.','No tenemos por qué perder la humanidad.','Prefiero compartir antes que discutir.','Nadie debería pasar por esto solo.'],['Tell me if you need help.','We do not have to lose our humanity.','I would rather share than argue.','Nobody should go through this alone.']),
'cautious':(['Todavía no sé si puedo fiarme.','Paso a paso. Primero observamos.','Mantengamos una salida libre.','No me acerco sin mirar antes.'],['I still do not know if I can trust you.','Step by step. First we watch.','Let us keep an exit clear.','I look before getting close.']),
'pragmatic':(['Lo importante es que sirva.','Contemos lo que nos queda.','Sin suministros no llegaremos lejos.','Menos ruido, más resultados.'],['What matters is that it works.','Let us count what we have left.','Without supplies we will not get far.','Less noise, more results.']),
'brave':(['Si vienen, no pienso rendirme.','Yo vigilo mientras te recuperas.','Podemos salir de esta.','Tengo miedo, pero no voy a quedarme paralizado.'],['If they come, I am not giving up.','I will keep watch while you recover.','We can get through this.','I am afraid, but I will not freeze.']),
'nervous':(['¿Has oído eso?','Ojalá no venga nadie más.','Me cuesta quedarme quieto.','No me gusta lo que hay ahí fuera.'],['Did you hear that?','I hope nobody else comes.','It is hard to stand still.','I do not like what is out there.']),
'grumpy':(['No me hagas perder el tiempo.','Ya he oído suficientes promesas.','Dime qué necesitas y terminamos.','No confundas paciencia con amistad.'],['Do not waste my time.','I have heard enough promises.','Tell me what you need and let us finish.','Do not mistake patience for friendship.']),
'joker':(['Si sobrevivimos, invitas tú.','Esto necesita menos zombis y más café.','Mi plan favorito es seguir respirando.','Por lo menos no hay atasco para ir al trabajo.'],['If we survive, you are buying.','This needs fewer zombies and more coffee.','My favorite plan is to keep breathing.','At least there is no traffic on the commute.']),
'quiet':(['Sí. Te escucho.','No suelo hablar mucho.','Prefiero observar.','Gracias por preguntar.'],['Yes. I am listening.','I do not talk much.','I prefer to observe.','Thank you for asking.'])}
for name,(a,b)in personas.items():
 for loc,lines in [('es_es',a),('en_us',b)]:
  for i,text in enumerate(lines):labels[loc]['dialog.soc.persona.'+name+'.'+str(i)]=text
